  def test_tests_vacuum_ray_32_on_square
    it = G.seed(Physics.SQUARE4, 4, 1)
    guard = 0
    until (Ops.eq(it.ticks, 3) && Ops.gt(it.margin, 0))
      guard += 1
      skip("the refinement never held") if guard > 5 || !it.respond_to?(:tick)
      it.tick
    end
    assert(Ops.m_every(it.vertices, ->(v) {
  return Ops.m_every(v.at.components, ->(c) {
