  })
}), "Ops.m_every(it.vertices, ->(v) {\n  return Ops.m_every(v.at.components, ->(c) {\n    return (Ops.ge(c, Ops.sub(0, it.margin)) && Ops.lt(c, Ops.add(it.N, it.margin)))\n  })\n})")
