    assert(Ops.le(it.points, it.vertices.length), "Ops.le(it.points, it.vertices.length)")
  end

  def test_tests_vacuum_ray_44_on_frontier
    it = G.seed(Physics.SQUARE4, 3, 5, 250000, 2)
    guard = 0
    until ((Ops.eq(it.ticks, 4) && Ops.m_empty(it.sources)) && Ops.eq(it.margin, 0))
      guard += 1
      skip("the refinement never held") if guard > 6 || !it.respond_to?(:tick)
      it.tick
    end
    assert(Ops.le(it.points, it.vertices.length), "Ops.le(it.points, it.vertices.length)")
  end
end
